def is_simple_power(x, n):
    """
    Return True if x is a simple power of n, otherwise False.

    x is a simple power of n if there exists a non-negative integer k
    such that n ** k == x.
    """
    if x == 1:
        return True

    if n == 1:
        return False

    if n == 0:
        return x == 0

    if n == -1:
        return x == -1

    if x == 0:
        return False

    if n > 0:
        if x < 0:
            return False

        while x % n == 0:
            x //= n

        return x == 1

    # Handle negative bases less than -1.
    base = -n
    value = abs(x)
    exponent = 0

    while value % base == 0:
        value //= base
        exponent += 1

    if value != 1:
        return False

    if x > 0:
        return exponent % 2 == 0

    return exponent % 2 == 1


