def count_up_to(n):
    """
    Return a list of all prime numbers less than n.

    Examples:
        count_up_to(5)  => [2, 3]
        count_up_to(11) => [2, 3, 5, 7]
        count_up_to(0)  => []
    """
    primes = []

    for candidate in range(2, n):
        is_prime = True

        for prime in primes:
            if prime * prime > candidate:
                break
            if candidate % prime == 0:
                is_prime = False
                break

        if is_prime:
            primes.append(candidate)

    return primes

